describe('Full Checkout Process - Sauce Labs Backpack', () => {
  beforeEach(() => {
    cy.visit('https://www.saucedemo.com');
    cy.get('[data-testid="login-button"]').click();
    cy.get('[data-testid="email-input"]').type('standard_user@example.com');
    cy.get('[data-testid="password-input"]').type('secret_sauce');
    cy.get('[data-testid="login-button"]').click();
  });

  it('should complete checkout and confirm order successfully', () => {
    // Add backpack to cart
    cy.get('[data-testid="add-to-cart-sauce-labs-backpack"]').click();
    cy.get('[data-testid="cart-link"]').click();

    // Verify cart information form is displayed
    cy.get('[data-testid="checkout-form"]').should('be.visible');

    // Fill checkout form
    cy.get('[data-testid="firstName"]').type('Saif');
    cy.get('[data-testid="lastName"]').type('Afzal');
    cy.get('[data-testid="postalCode"]').type('201301');
    cy.get('[data-testid="continue-button"]').click();

    // Verify overview page is displayed
    cy.get('[data-testid="order-summary"]').should('be.visible');
    cy.get('[data-testid="order-summary"]').should('contain', 'Backpack');

    // Verify total is displayed
    cy.get('[data-testid="total-price"]').should('be.visible');
    cy.get('[data-testid="total-price"]').should('contain', '$19.99');

    // Verify shipping options are displayed
    cy.get('[data-testid="shipping-options"]').should('be.visible');

    // Verify payment options are displayed
    cy.get('[data-testid="payment-methods"]').should('be.visible');

    // Verify continue button is visible
    cy.get('[data-testid="continue-button"]').should('be.visible');

    // Click continue button
    cy.get('[data-testid="continue-button"]').click();

    // Verify confirmation header is displayed
    cy.get('[data-testid="complete-header"]').should('be.visible');
    cy.get('[data-testid="complete-header"]').should('contain', 'Thank you for your order!');

    // Verify success message
    cy.get('[data-testid="success-message"]').should('be.visible');
    cy.get('[data-testid="success-message"]').should('contain', 'Order confirmed');

    // Verify order details are visible
    cy.get('[data-testid="order-details"]').should('be.visible');
    cy.get('[data-testid="order-details"]').should('contain', 'Backpack');

    // Verify order number is displayed
    cy.get('[data-testid="order-number"]').should('be.visible');
    cy.get('[data-testid="order-number"]').should('contain', '123456');

    // Verify order status is 'Processing'
    cy.get('[data-testid="order-status"]').should('contain', 'Processing');

    // Verify order is in the cart
    cy.get('[data-testid="cart-item"]').should('be.visible');

    // Verify checkout button is still visible
    cy.get('[data-testid="checkout-button"]').should('be.visible');

    // Verify order can be canceled
    cy.get('[data-testid="cancel-order-button"]').should('be.visible');
  });

  it('should handle edge case when shipping address is invalid', () => {
    // Add backpack to cart
    cy.get('[data-testid="add-to-cart-sauce-labs-backpack"]').click();
    cy.get('[data-testid="cart-link"]').click();

    // Fill checkout form with valid details
    cy.get('[data-testid="firstName"]').type('Saif');
    cy.get('[data-testid="lastName"]').type('Afzal');
    cy.get('[data-testid="postalCode"]').type('201301');
    cy.get('[data-testid="continue-button"]').click();

    // Verify shipping address validation error
    cy.get('[data-testid="shipping-address-error"]').should('be.visible');
    cy.get('[data-testid="shipping-address-error"]').should('contain', 'Please enter a valid address');

    // Verify error message is displayed
    cy.get('[data-testid="error-message"]').should('be.visible');
    cy.get('[data-testid="error-message"]').should('contain', 'Invalid shipping address');

    // Verify user can correct the address
    cy.get('[data-testid="shipping-address-input"]').type('123 Main St, Anytown, USA');
    cy.get('[data-testid="continue-button"]').click();

    // Verify error message disappears
    cy.get('[data-testid="shipping-address-error"]').should('not.exist');

    // Verify order continues to process
    cy.get('[data-testid="order-status"]').should('contain', 'Processing');

    // Verify order can be canceled
    cy.get('[data-testid="cancel-order-button"]').should('be.visible');
  });
});
